    private static void add(Map<String,Entry> out,String id,String family,Band band,Kind kind,String type,String output,int count,String craft,int souls,int duration,int ingredients,String research,String sacrifice,String convert,int xp){
        if(out.putIfAbsent(id,new Entry(family,band,kind,type,output,count,craft,souls,duration,ingredients,research,sacrifice,convert,xp))!=null)throw new IllegalStateException("Duplicate Goety ritual "+id);
    }
    public static Entry lookup(String id){return id==null?null:ENTRIES.get(id);}
    public static Map<String,Entry> entries(){return ENTRIES;}
    public static Map<String,String> excluded(){return Map.of("goety:summon_apostle","Boss preparation","goety:summon_apostle2","Boss preparation");}
    public static void addTo(Map<String,RitualRewards.Rule> out){ENTRIES.forEach((id,e)->{if(out.putIfAbsent(id,e.rule())!=null)throw new IllegalStateException("Duplicate ritual "+id);});}
